#!/usr/bin/env python3
"""Maintain and validate the PavuLLMo static experiment tracker dataset."""

from __future__ import annotations

import argparse
import csv
import datetime as dt
import json
from pathlib import Path
import re
import sys
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DATA_PATH = ROOT / "docs" / "data" / "tracker.json"
DEFAULT_JS_PATH = ROOT / "docs" / "data" / "tracker.js"

JS_PREFIX = (
    "// Auto-generated from docs/data/tracker.json by tools/update_tracker.py.\n"
    "// Do not edit this file directly; run `python3 tools/update_tracker.py build`.\n"
    "window.PAVULLMO_TRACKER_DATA = "
)
JS_SUFFIX = ";\n"

VALID_ABLATION_CATEGORIES = (
    "Architecture",
    "Optimizer & Schedule",
    "Tokenizer",
    "Dataset & Cleaning",
    "Evaluation",
)
VALID_ABLATION_STATUSES = (
    "Promoted",
    "Rejected",
    "Diagnostic",
    "Mixed",
    "Promising",
)
BENCHMARK_CATEGORIES = (
    ("icl", "icl"),
    ("knowledge", "knowledge"),
    ("language-manipulation", "language_manipulation"),
    ("math", "math"),
    ("math-languages", "math_languages"),
    ("reasoning", "reasoning"),
)
BENCHMARK_FIELDS = ("overall_bidir",) + tuple(field for _, field in BENCHMARK_CATEGORIES)


def _is_iso_date(value: Any) -> bool:
    if not isinstance(value, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        return False
    try:
        dt.date.fromisoformat(value)
        return True
    except ValueError:
        return False


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def parse_js_payload(js_text: str) -> dict[str, Any]:
    """Extract and parse the JSON payload from tracker.js."""
    marker = "window.PAVULLMO_TRACKER_DATA ="
    idx = js_text.find(marker)
    if idx < 0:
        raise ValueError("tracker.js is missing `window.PAVULLMO_TRACKER_DATA =` assignment")
    body = js_text[idx + len(marker) :].strip()
    if body.endswith(";"):
        body = body[:-1].strip()
    payload = json.loads(body)
    if not isinstance(payload, dict):
        raise ValueError("tracker.js payload must be a JSON object")
    return payload


def validate_tracker_data(data: Any, js_path: Path | None = None) -> list[str]:
    """Validate tracker JSON structure, foreign keys, numeric ranges, and JS mirror."""
    errors: list[str] = []
    if not isinstance(data, dict):
        return ["Top-level tracker payload must be a JSON object."]

    for key in (
        "project",
        "repo_url",
        "updated_at",
        "benchmark_note",
        "model_versions",
        "training_runs",
        "ablations",
    ):
        if key not in data:
            errors.append(f"Missing top-level key `{key}`.")

    if "updated_at" in data and not _is_iso_date(data["updated_at"]):
        errors.append(f"Invalid top-level `updated_at` date: {data.get('updated_at')!r}")

    version_ids: set[str] = set()
    versions = data.get("model_versions")
    if not isinstance(versions, list) or not versions:
        errors.append("`model_versions` must be a non-empty list.")
    else:
        for idx, ver in enumerate(versions):
            if not isinstance(ver, dict):
                errors.append(f"model_versions[{idx}] must be an object.")
                continue
            vid = ver.get("id")
            if not isinstance(vid, str) or not vid.strip():
                errors.append(f"model_versions[{idx}] missing non-empty `id`.")
            elif vid in version_ids:
                errors.append(f"Duplicate model_versions id `{vid}`.")
            else:
                version_ids.add(vid)

            for req in (
                "name",
                "commit",
                "branch",
                "params_label",
                "positional_encoding",
                "attention_variant",
                "optimizer_summary",
            ):
                if not isinstance(ver.get(req), str) or not ver[req].strip():
                    errors.append(f"model_versions[{vid or idx}] missing non-empty `{req}`.")

            if not _is_iso_date(ver.get("commit_date")):
                errors.append(
                    f"model_versions[{vid or idx}] invalid `commit_date`: {ver.get('commit_date')!r}"
                )

            params = ver.get("total_params")
            if not isinstance(params, int) or isinstance(params, bool) or params <= 0:
                errors.append(
                    f"model_versions[{vid or idx}] `total_params` must be a positive int."
                )

            arch = ver.get("architecture")
            if not isinstance(arch, dict) or not all(
                k in arch for k in ("layers", "embed_dim", "ffn_type", "ffn_dim", "seq_len")
            ):
                errors.append(f"model_versions[{vid or idx}] incomplete `architecture` object.")

            tok = ver.get("tokenizer")
            if not isinstance(tok, dict) or not all(
                k in tok for k in ("vocab_size", "type", "artifact")
            ):
                errors.append(f"model_versions[{vid or idx}] incomplete `tokenizer` object.")

    run_ids: set[str] = set()
    runs = data.get("training_runs")
    if not isinstance(runs, list) or not runs:
        errors.append("`training_runs` must be a non-empty list.")
    else:
        for idx, run in enumerate(runs):
            if not isinstance(run, dict):
                errors.append(f"training_runs[{idx}] must be an object.")
                continue
            rid = run.get("id")
            if not isinstance(rid, str) or not rid.strip():
                errors.append(f"training_runs[{idx}] missing non-empty `id`.")
            elif rid in run_ids:
                errors.append(f"Duplicate training_runs id `{rid}`.")
            else:
                run_ids.add(rid)

            for req in ("name", "dataset_name", "tokens_label"):
                if not isinstance(run.get(req), str) or not run[req].strip():
                    errors.append(f"training_runs[{rid or idx}] missing non-empty `{req}`.")

            if not _is_iso_date(run.get("date")):
                errors.append(f"training_runs[{rid or idx}] invalid `date`: {run.get('date')!r}")

            ver_id = run.get("version_id")
            if not isinstance(ver_id, str) or ver_id not in version_ids:
                errors.append(
                    f"training_runs[{rid or idx}] unknown `version_id`: {ver_id!r}"
                )

            for loss_key in ("train_loss", "val_loss", "val_loss_prefix", "test_loss"):
                val = run.get(loss_key)
                if val is not None and (not _is_number(val) or val < 0):
                    errors.append(
                        f"training_runs[{rid or idx}] invalid `{loss_key}`: {val!r}"
                    )

            benches = run.get("benchmarks")
            if benches is not None:
                if not isinstance(benches, dict):
                    errors.append(f"training_runs[{rid or idx}] `benchmarks` must be dict/null.")
                else:
                    for bfield in BENCHMARK_FIELDS:
                        bval = benches.get(bfield)
                        if not _is_number(bval) or not (0.0 <= float(bval) <= 1.0):
                            errors.append(
                                f"training_runs[{rid or idx}] benchmark `{bfield}` "
                                f"out of [0, 1]: {bval!r}"
                            )

    ablation_ids: set[str] = set()
    ablations = data.get("ablations")
    if not isinstance(ablations, list) or not ablations:
        errors.append("`ablations` must be a non-empty list.")
    else:
        for idx, abl in enumerate(ablations):
            if not isinstance(abl, dict):
                errors.append(f"ablations[{idx}] must be an object.")
                continue
            aid = abl.get("id")
            if not isinstance(aid, str) or not aid.strip():
                errors.append(f"ablations[{idx}] missing non-empty `id`.")
            elif aid in ablation_ids:
                errors.append(f"Duplicate ablations id `{aid}`.")
            else:
                ablation_ids.add(aid)

            if not _is_iso_date(abl.get("date")):
                errors.append(f"ablations[{aid or idx}] invalid `date`: {abl.get('date')!r}")

            if abl.get("category") not in VALID_ABLATION_CATEGORIES:
                errors.append(
                    f"ablations[{aid or idx}] invalid `category`: {abl.get('category')!r}"
                )
            if abl.get("status") not in VALID_ABLATION_STATUSES:
                errors.append(
                    f"ablations[{aid or idx}] invalid `status`: {abl.get('status')!r}"
                )

            for req in ("title", "testing", "results", "conclusion", "source"):
                if not isinstance(abl.get(req), str) or not abl[req].strip():
                    errors.append(f"ablations[{aid or idx}] missing non-empty `{req}`.")

    if js_path is not None:
        if not js_path.exists():
            errors.append(f"Missing JS bundle mirror at {js_path}")
        else:
            try:
                js_payload = parse_js_payload(js_path.read_text(encoding="utf-8"))
                if js_payload != data:
                    errors.append(
                        f"{js_path} is out of sync with tracker JSON; run `build`."
                    )
            except (OSError, ValueError, json.JSONDecodeError) as exc:
                errors.append(f"Failed to parse {js_path}: {exc}")

    return errors


def load_json(path: Path) -> dict[str, Any]:
    """Load tracker JSON from disk."""
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise ValueError(f"{path} must contain a top-level JSON object")
    return payload


def write_tracker_bundle(
    data: dict[str, Any],
    data_path: Path,
    js_path: Path,
    *,
    write_json: bool = True,
) -> None:
    """Write formatted tracker.json (optional) and synced tracker.js bundle."""
    rendered = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
    if write_json:
        data_path.parent.mkdir(parents=True, exist_ok=True)
        data_path.write_text(rendered, encoding="utf-8")
    js_path.parent.mkdir(parents=True, exist_ok=True)
    js_path.write_text(JS_PREFIX + rendered.rstrip("\n") + JS_SUFFIX, encoding="utf-8")


def parse_config_string(config_str: str) -> dict[str, str]:
    """Parse either legacy semicolon config or single-line TOML `config = { ... }`."""
    parsed: dict[str, str] = {}
    stripped = config_str.strip()
    if stripped.startswith("config = {"):
        for match in re.finditer(
            r'([a-zA-Z0-9_]+)\s*=\s*("[^"]*"|true|false|[0-9eE.+\-]+)', stripped
        ):
            parsed[match.group(1)] = match.group(2).strip('"')
        return parsed

    for part in stripped.split(";"):
        if "=" in part:
            key, val = part.split("=", 1)
            parsed[key.strip()] = val.strip()
    return parsed


def load_csv_run(csv_path: Path, experiment_name: str) -> dict[str, Any]:
    """Read the latest matching experiment row from pretrain_runs.csv."""
    with csv_path.open("r", encoding="utf-8", newline="") as handle:
        matches = [
            row
            for row in csv.DictReader(handle)
            if row.get("experiment_name") == experiment_name
        ]
    if not matches:
        raise ValueError(f"Experiment `{experiment_name}` not found in {csv_path}")
    latest = matches[-1]
    cfg = parse_config_string(latest.get("config", ""))
    return {
        "name": latest["experiment_name"],
        "dataset_variant": latest.get("dataset_variant", ""),
        "train_loss": _parse_optional_float(latest.get("train_loss")),
        "validation_loss": _parse_optional_float(latest.get("validation_loss")),
        "config": cfg,
    }


def _parse_optional_float(raw: Any) -> float | None:
    if raw is None or raw == "":
        return None
    return float(raw)


def load_eval_json(eval_path: Path, eval_key: str) -> dict[str, Any]:
    """Extract loss and 6-category benchmark fields from an evaluation JSON file."""
    payload = json.loads(eval_path.read_text(encoding="utf-8"))
    if isinstance(payload.get("evaluations"), dict):
        evals = payload["evaluations"]
        if eval_key not in evals:
            available = ", ".join(sorted(evals))
            raise KeyError(
                f"Eval key `{eval_key}` not found in {eval_path} (available: {available})"
            )
        record = evals[eval_key]
    else:
        record = payload

    benchmarks = None
    cat_bidir = record.get("benchmark_category_bidir")
    overall = record.get("benchmark_overall_bidir")
    if isinstance(cat_bidir, dict) and overall is not None:
        benchmarks = {"overall_bidir": round(float(overall), 4)}
        for dir_name, field_name in BENCHMARK_CATEGORIES:
            if dir_name not in cat_bidir:
                raise KeyError(
                    f"Missing category `{dir_name}` in benchmark_category_bidir"
                )
            benchmarks[field_name] = round(float(cat_bidir[dir_name]), 4)

    return {
        "train_loss": _parse_optional_float(record.get("final_train_loss")),
        "val_loss": _parse_optional_float(record.get("full_val_loss")),
        "test_loss": _parse_optional_float(record.get("full_test_loss")),
        "benchmarks": benchmarks,
    }


def load_benchmarks_dir(scores_root: Path, model_dir_name: str) -> dict[str, float]:
    """Compute category and overall macro bidirectional accuracy from benchmark JSONs."""
    benchmarks: dict[str, float] = {}
    cat_means: list[float] = []
    for dir_name, field_name in BENCHMARK_CATEGORIES:
        cat_dir = scores_root / dir_name / model_dir_name
        if not cat_dir.is_dir():
            raise FileNotFoundError(f"Missing benchmark category directory: {cat_dir}")
        scores: list[float] = []
        for score_file in sorted(cat_dir.glob("*-bench-scores.json")):
            payload = json.loads(score_file.read_text(encoding="utf-8"))
            val = payload.get("metrics", {}).get("macro_bidirectional_accuracy")
            if val is None:
                raise KeyError(
                    f"Missing metrics.macro_bidirectional_accuracy in {score_file}"
                )
            scores.append(float(val))
        if not scores:
            raise ValueError(f"No *-bench-scores.json files found in {cat_dir}")
        mean_val = sum(scores) / len(scores)
        benchmarks[field_name] = round(mean_val, 4)
        cat_means.append(mean_val)

    benchmarks["overall_bidir"] = round(sum(cat_means) / len(cat_means), 4)
    return benchmarks


def _upsert_by_id(
    items: list[dict[str, Any]],
    entry: dict[str, Any],
    *,
    replace: bool,
    prepend: bool = True,
) -> list[dict[str, Any]]:
    entry_id = entry["id"]
    existing_idx = next((i for i, item in enumerate(items) if item.get("id") == entry_id), None)
    if existing_idx is not None:
        if not replace:
            raise ValueError(f"Entry `{entry_id}` already exists; pass --replace to update.")
        updated = list(items)
        updated[existing_idx] = entry
        return updated
    return ([entry] + list(items)) if prepend else (list(items) + [entry])


def cmd_validate(args: argparse.Namespace) -> int:
    data = load_json(args.data)
    errors = validate_tracker_data(data, js_path=args.js)
    if errors:
        for err in errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1
    print(
        "OK: "
        f"{len(data['model_versions'])} model_versions, "
        f"{len(data['training_runs'])} training_runs, "
        f"{len(data['ablations'])} ablations validated (JSON & JS in sync)."
    )
    return 0


def cmd_build(args: argparse.Namespace) -> int:
    data = load_json(args.data)
    if args.touch_date:
        data["updated_at"] = dt.date.today().isoformat()
    write_tracker_bundle(data, args.data, args.js, write_json=args.touch_date)
    errors = validate_tracker_data(data, js_path=args.js)
    if errors:
        for err in errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1
    print(
        f"Built {args.js} ({len(data['model_versions'])} versions, "
        f"{len(data['training_runs'])} runs, {len(data['ablations'])} ablations)."
    )
    return 0


def cmd_add_run(args: argparse.Namespace) -> int:
    data = load_json(args.data)
    name = args.name
    dataset_name = args.dataset
    train_loss = args.train_loss
    val_loss = args.val_loss
    val_scope = args.val_scope
    val_prefix = args.val_prefix
    test_loss = args.test_loss
    test_scope = args.test_scope
    benchmarks: dict[str, float] | None = None

    if args.from_csv:
        exp_name = args.experiment or args.name or args.id
        if not exp_name:
            raise ValueError("--from-csv requires --experiment or --name/--id")
        csv_row = load_csv_run(args.from_csv, exp_name)
        name = name or csv_row["name"]
        dataset_name = dataset_name or csv_row["dataset_variant"]
        if train_loss is None:
            train_loss = csv_row["train_loss"]
        if val_loss is None:
            val_loss = csv_row["validation_loss"]
            val_scope = val_scope or "prefix"

    if args.eval_json:
        ev = load_eval_json(args.eval_json, args.eval_key)
        if train_loss is None:
            train_loss = ev["train_loss"]
        if ev["val_loss"] is not None:
            if val_loss is not None and val_prefix is None and val_scope == "prefix":
                val_prefix = val_loss
            val_loss = ev["val_loss"]
            val_scope = args.val_scope or "full 10M"
        if ev["test_loss"] is not None and test_loss is None:
            test_loss = ev["test_loss"]
            test_scope = args.test_scope or "full 10M"
        if ev["benchmarks"] is not None:
            benchmarks = ev["benchmarks"]

    if args.benchmarks_dir:
        b_model = args.benchmark_model or name or args.id
        if not b_model:
            raise ValueError("--benchmarks-dir requires --benchmark-model or --name/--id")
        benchmarks = load_benchmarks_dir(args.benchmarks_dir, b_model)

    run_id = args.id or name
    if not run_id or not name:
        raise ValueError("Run `--id` or `--name` is required.")
    if not dataset_name:
        raise ValueError("`--dataset` is required (or inferred via --from-csv).")

    entry: dict[str, Any] = {
        "id": run_id,
        "name": name,
        "date": args.date,
        "version_id": args.version_id,
        "dataset_name": dataset_name,
        "tokens_label": args.tokens,
        "train_loss": round(train_loss, 4) if train_loss is not None else None,
        "val_loss": round(val_loss, 4) if val_loss is not None else None,
        "val_loss_scope": val_scope if val_loss is not None else None,
        "val_loss_prefix": round(val_prefix, 4) if val_prefix is not None else None,
        "test_loss": round(test_loss, 4) if test_loss is not None else None,
        "test_loss_scope": test_scope if test_loss is not None else None,
        "benchmarks": benchmarks,
        "notes": args.notes,
    }

    runs = _upsert_by_id(data["training_runs"], entry, replace=args.replace, prepend=True)
    runs.sort(key=lambda r: r["date"], reverse=True)
    data["training_runs"] = runs
    data["updated_at"] = dt.date.today().isoformat()

    errors = validate_tracker_data(data, js_path=None)
    if errors:
        for err in errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1
    write_tracker_bundle(data, args.data, args.js, write_json=True)
    print(f"Saved run `{run_id}` and rebuilt {args.js}.")
    return 0


def cmd_add_version(args: argparse.Namespace) -> int:
    data = load_json(args.data)
    entry: dict[str, Any] = {
        "id": args.id,
        "name": args.name,
        "commit": args.commit,
        "commit_date": args.commit_date,
        "branch": args.branch,
        "total_params": args.total_params,
        "params_label": args.params_label,
        "architecture": {
            "layers": args.layers,
            "embed_dim": args.embed_dim,
            "ffn_type": args.ffn_type,
            "ffn_dim": args.ffn_dim,
            "seq_len": args.seq_len,
            "tied_embeddings": not args.untied_embeddings,
        },
        "tokenizer": {
            "vocab_size": args.vocab_size,
            "type": args.tokenizer_type,
            "artifact": args.tokenizer_artifact,
        },
        "positional_encoding": args.pos_encoding,
        "attention_variant": args.attention_variant,
        "optimizer_summary": args.optimizer_summary,
        "optimizer_details": {
            "optimizers": args.optimizers,
            "lr": args.lr,
            "schedule": args.schedule,
            "weight_decay": args.weight_decay,
            "batch_size": args.batch_size,
            "init": args.init,
            "ema": args.ema,
        },
        "notes": args.notes,
    }
    data["model_versions"] = _upsert_by_id(
        data["model_versions"], entry, replace=args.replace, prepend=True
    )
    data["updated_at"] = dt.date.today().isoformat()

    errors = validate_tracker_data(data, js_path=None)
    if errors:
        for err in errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1
    write_tracker_bundle(data, args.data, args.js, write_json=True)
    print(f"Saved model version `{args.id}` and rebuilt {args.js}.")
    return 0


def cmd_add_ablation(args: argparse.Namespace) -> int:
    data = load_json(args.data)
    entry: dict[str, Any] = {
        "id": args.id,
        "date": args.date,
        "title": args.title,
        "category": args.category,
        "status": args.status,
        "testing": args.testing,
        "results": args.results,
        "conclusion": args.conclusion,
        "source": args.source,
    }
    data["ablations"] = _upsert_by_id(
        data["ablations"], entry, replace=args.replace, prepend=True
    )
    data["updated_at"] = dt.date.today().isoformat()

    errors = validate_tracker_data(data, js_path=None)
    if errors:
        for err in errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1
    write_tracker_bundle(data, args.data, args.js, write_json=True)
    print(f"Saved ablation `{args.id}` and rebuilt {args.js}.")
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data", type=Path, default=DEFAULT_DATA_PATH)
    parser.add_argument("--js", type=Path, default=DEFAULT_JS_PATH)
    sub = parser.add_subparsers(dest="command", required=True)

    p_val = sub.add_parser("validate", help="Validate tracker.json and tracker.js sync.")
    p_val.set_defaults(func=cmd_validate)

    p_bld = sub.add_parser("build", help="Generate tracker.js from tracker.json.")
    p_bld.add_argument("--touch-date", action="store_true", help="Update updated_at to today.")
    p_bld.set_defaults(func=cmd_build)

    p_run = sub.add_parser("add-run", help="Add or update a training run entry.")
    p_run.add_argument("--id", help="Unique run ID (defaults to --name).")
    p_run.add_argument("--name", help="Display run name.")
    p_run.add_argument("--date", default=dt.date.today().isoformat(), help="YYYY-MM-DD date.")
    p_run.add_argument("--version-id", required=True, help="Existing model_versions[].id.")
    p_run.add_argument("--dataset", help="Dataset name/description.")
    p_run.add_argument("--tokens", required=True, help="Token budget label (e.g. '1.00B tok').")
    p_run.add_argument("--train-loss", type=float)
    p_run.add_argument("--val-loss", type=float)
    p_run.add_argument("--val-scope", default=None)
    p_run.add_argument("--val-prefix", type=float, default=None)
    p_run.add_argument("--test-loss", type=float)
    p_run.add_argument("--test-scope", default=None)
    p_run.add_argument("--from-csv", type=Path, help="Optional pretrain_runs.csv path.")
    p_run.add_argument("--experiment", help="Experiment name to match inside --from-csv.")
    p_run.add_argument("--eval-json", type=Path, help="Optional eval summary JSON path.")
    p_run.add_argument("--eval-key", default="final_ema", help="Key inside evaluations dict.")
    p_run.add_argument("--benchmarks-dir", type=Path, help="Optional benchmarks/scores root.")
    p_run.add_argument("--benchmark-model", help="Subdirectory name under each category.")
    p_run.add_argument("--notes", default="")
    p_run.add_argument("--replace", action="store_true")
    p_run.set_defaults(func=cmd_add_run)

    p_ver = sub.add_parser("add-version", help="Add or update a model & optimizer version.")
    p_ver.add_argument("--id", required=True)
    p_ver.add_argument("--name", required=True)
    p_ver.add_argument("--commit", required=True)
    p_ver.add_argument("--commit-date", default=dt.date.today().isoformat())
    p_ver.add_argument("--branch", default="main")
    p_ver.add_argument("--total-params", type=int, required=True)
    p_ver.add_argument("--params-label", required=True)
    p_ver.add_argument("--layers", type=int, required=True)
    p_ver.add_argument("--embed-dim", type=int, required=True)
    p_ver.add_argument("--ffn-type", default="SwiGLU")
    p_ver.add_argument("--ffn-dim", type=int, required=True)
    p_ver.add_argument("--seq-len", type=int, default=1024)
    p_ver.add_argument("--untied-embeddings", action="store_true")
    p_ver.add_argument("--vocab-size", type=int, required=True)
    p_ver.add_argument("--tokenizer-type", default="SentencePiece BPE")
    p_ver.add_argument("--tokenizer-artifact", default="production_16k")
    p_ver.add_argument("--pos-encoding", required=True)
    p_ver.add_argument("--attention-variant", required=True)
    p_ver.add_argument("--optimizer-summary", required=True)
    p_ver.add_argument("--optimizers", required=True)
    p_ver.add_argument("--lr", required=True)
    p_ver.add_argument("--schedule", required=True)
    p_ver.add_argument("--weight-decay", required=True)
    p_ver.add_argument("--batch-size", required=True)
    p_ver.add_argument("--init", default="gpt_scaled (std=0.02)")
    p_ver.add_argument("--ema", default="None")
    p_ver.add_argument("--notes", default="")
    p_ver.add_argument("--replace", action="store_true")
    p_ver.set_defaults(func=cmd_add_version)

    p_abl = sub.add_parser("add-ablation", help="Add or update a documented ablation.")
    p_abl.add_argument("--id", required=True)
    p_abl.add_argument("--date", default=dt.date.today().isoformat())
    p_abl.add_argument("--title", required=True)
    p_abl.add_argument("--category", required=True, choices=VALID_ABLATION_CATEGORIES)
    p_abl.add_argument("--status", required=True, choices=VALID_ABLATION_STATUSES)
    p_abl.add_argument("--testing", required=True)
    p_abl.add_argument("--results", required=True)
    p_abl.add_argument("--conclusion", required=True)
    p_abl.add_argument("--source", required=True)
    p_abl.add_argument("--replace", action="store_true")
    p_abl.set_defaults(func=cmd_add_ablation)

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        return args.func(args)
    except (OSError, ValueError, KeyError, json.JSONDecodeError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
